cd /gin && cat > zz_scratch_test.go <<'EOF'
package gin

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestZZCIMulti(t *testing.T) {
	defer func() {
		if r := recover(); r != nil {
			t.Logf("PANIC: %v", r)
		}
	}()
	tree := &node{}
	tree.addRoute("/cmd/:tool/", fakeHandler("/cmd/:tool/"))
	tree.addRoute("/cmd/x", fakeHandler("/cmd/x"))
	p, ok := tree.findCaseInsensitivePath("/CMD/X", true)
	t.Logf("ci /CMD/X -> %q %v", p, ok)
	p, ok = tree.findCaseInsensitivePath("/CMD/Y", true)
	t.Logf("ci /CMD/Y -> %q %v", p, ok)
}

func TestZZRWStatus(t *testing.T) {
	testWriter := httptest.NewRecorder()
	writer := &responseWriter{}
	writer.reset(testWriter)
	w := ResponseWriter(writer)

	w.WriteHeader(http.StatusOK)
	w.WriteHeaderNow()
	t.Logf("after OK: status=%d code=%d", w.Status(), testWriter.Code)

	w.WriteHeader(http.StatusNotFound)
	t.Logf("after 404: status=%d code=%d", w.Status(), testWriter.Code)

	testWriter2 := httptest.NewRecorder()
	writer2 := &responseWriter{}
	writer2.reset(testWriter2)
	w2 := ResponseWriter(writer2)
	w2.WriteHeader(http.StatusNotFound)
	w2.WriteHeaderNow()
	t.Logf("404 first: status=%d code=%d", w2.Status(), testWriter2.Code)
}
EOF
go test -run 'TestZZ' -v . 2>&1 | head -40

cd /gin && cat > zz_v_test.go <<'EOF'
package gin

import (
	"errors"
	"testing"
)

func TestZZUnwrapValue(t *testing.T) {
	inner := TestErr("some error")
	err := Error{Err: inner, Type: ErrorTypeAny}
	t.Log("errors.Is:", errors.Is(err, inner))
	var te TestErr
	t.Log("errors.As:", errors.As(err, &te))
	// pointer form still works
	err2 := &Error{Err: inner, Type: ErrorTypeAny}
	t.Log("ptr errors.Is:", errors.Is(err2, inner))
}
EOF
go test -run TestZZUnwrapValue -v . 2>&1 | head -12; rm zz_v_test.go; go test ./... 2>&1 | tail -6; git diff --stat
